package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStream_isJSIdentifier_TriageGen2Test {









    @Test
    public void testIsJSIdentifier_InvalidPartChar() {
        // Valid start, but invalid part (contains a hyphen or space)
        assertFalse(TokenStream.isJSIdentifier("a-b"));
        assertFalse(TokenStream.isJSIdentifier("a b"));
        assertFalse(TokenStream.isJSIdentifier("a.b"));
        assertFalse(TokenStream.isJSIdentifier("abc!"));
    }


}

